    local goodsEnv = CfUtils.GetLuaScr(self.GoodNode.gameObject, "Game.Behaviours.GoodNodeMB")
    if not KTool.IsNull(goodsEnv) then
        goodsEnv:Reload({ goodsId = goodsId })
        goodsEnv:SetClickButtonAction(function(goodsId)
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
